func (c *current) onMain1(e any) (any, error) {
	return e, nil
}

func (p *parser) callonMain1() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onMain1(stack["e"])
}

func (c *current) onOr1(first, rest any) (any, error) {
	return foldLeft(first, rest), nil
}

func (p *parser) callonOr1() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onOr1(stack["first"], stack["rest"])
}

func (c *current) onAnd1(first, rest any) (any, error) {
	return foldLeft(first, rest), nil
}

func (p *parser) callonAnd1() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onAnd1(stack["first"], stack["rest"])
}

func (c *current) onPrefix2(x any) (any, error) {
	return &Not{Op: "!", X: x}, nil
}

func (p *parser) callonPrefix2() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onPrefix2(stack["x"])
}

func (c *current) onOperand3(e any) (any, error) {
	return e, nil
}

func (p *parser) callonOperand3() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onOperand3(stack["e"])
}

func (c *current) onComparison2(f, o, v any) (any, error) {
	return &Compare{Field: f.(string), Op: o.(string), Value: v.(string)}, nil
}

func (p *parser) callonComparison2() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onComparison2(stack["f"], stack["o"], stack["v"])
}

func (c *current) onComparison12(f, first, rest any) (any, error) {
	in := &In{Field: f.(string), Values: []string{first.(string)}}
	for _, r := range rest.([]any) {
		in.Values = append(in.Values, r.([]any)[3].(string))
	}
	return in, nil
}

func (p *parser) callonComparison12() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onComparison12(stack["f"], stack["first"], stack["rest"])
}

func (c *current) onOp1() (any, error) {
	return string(c.text), nil
}

func (p *parser) callonOp1() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onOp1()
}

